 protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);try{int dark=1;DwmSetWindowAttribute(Handle,20,ref dark,4);}catch{}}
 Label MakeLabel(string text,float size,Color color,int x,int y,int width,int height,bool bold){return new Label{Text=text,Font=new Font(bold?"Segoe UI Semibold":"Segoe UI",size),ForeColor=color,Bounds=new Rectangle(x,y,width,height),AutoEllipsis=true};}
 protected override void WndProc(ref Message m){if(m.Msg==0x0312 && m.WParam.ToInt32()==1)Stop("Emergency stop pressed");base.WndProc(ref m);}
 void Restore(){Show();WindowState=FormWindowState.Normal;Activate();}
 void Log(string text){if(closing)return;string line=DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine;if(!text.StartsWith("Agent idle; next prompt")){log.SelectionStart=log.TextLength;log.SelectionColor=Theme.Purple;log.AppendText(DateTime.Now.ToString("HH:mm:ss")+Environment.NewLine);log.SelectionColor=Theme.Muted;log.AppendText(text+Environment.NewLine+Environment.NewLine);log.ScrollToCaret();}if(log.TextLength>45000)log.Text=log.Text.Substring(log.TextLength-30000);try{Directory.CreateDirectory(Settings.Folder);string p=Path.Combine(Settings.Folder,"activity.log");if(File.Exists(p)&&new FileInfo(p).Length>2*1024*1024)File.Move(p,p+"."+DateTime.Now.ToString("yyyyMMddHHmmss"));File.AppendAllText(p,line);}catch{}}
 void SaveSettings(){settings.Prompt=prompt.Text;settings.DelaySeconds=(int)delay.Value;settings.MaxRepeats=(int)limit.Value;settings.SendWhenInitiallyIdle=initial.Checked;var c=conversations.SelectedItem as Conversation;if(c!=null)settings.ConversationId=c.Id;try{settings.Save();}catch{Log("Could not save preferences.");}}
 async Task<List<Conversation>> DiscoverAll(){var found=await Discovery.Find();var all=new List<Conversation>();foreach(var ep in found){try{all.AddRange(await ep.Conversations());}catch{}}endpoints.AddRange(found);return all.GroupBy(c=>c.Id).Select(g=>g.First()).OrderByDescending(c=>c.Modified).ToList();}
 async Task RefreshConversations(){if(discovering||engine.Armed)return;discovering=true;refresh.Enabled=false;start.Enabled=false;try{var all=await DiscoverAll();if(closing)return;conversations.Items.Clear();conversations.Items.AddRange(all.Cast<object>().ToArray());int index=all.FindIndex(c=>c.Id==settings.ConversationId);if(all.Count>0)conversations.SelectedIndex=index>=0?index:0;connectionBadge.Text=all.Count>0?"●  CONNECTED":"●  NO CONVERSATIONS";connectionBadge.ForeColor=all.Count>0?Theme.Mint:Theme.Muted;connection.Text=all.Count>0?"●  Connected to AntiGravity  ·  "+all.Count+" conversations":"No conversations found. Open a conversation in AntiGravity, then Refresh.";Log(all.Count>0?"Connected. Select a conversation and press Start repeating.":"AntiGravity service found, but no conversations are available.");if(all.Count>0)await RefreshUsage();}catch(Exception ex){connectionBadge.Text="●  DISCONNECTED";connectionBadge.ForeColor=Theme.Muted;connection.Text="Could not connect. Keep AntiGravity open, then Refresh.";Log("Connection failed: "+ex.GetType().Name);}finally{discovering=false;if(!closing){refresh.Enabled=true;start.Enabled=conversations.Items.Count>0&&!string.IsNullOrWhiteSpace(prompt.Text);}}}
 void StartRepeating(){var c=conversations.SelectedItem as Conversation;if(c==null||string.IsNullOrWhiteSpace(prompt.Text)){Log("Select a conversation and enter a prompt first.");return;}selectedId=c.Id;activePrompt=prompt.Text;epoch++;engine.DelaySeconds=(int)delay.Value;engine.MaxRepeats=(int)limit.Value;engine.SendInitially=initial.Checked;engine.Start();rotationAttempts.Clear();sessionStarted=DateTime.UtcNow;failures=0;SetRunning(true);SaveSettings();Log("Armed for \""+c.Title+"\" ("+c.Id+"). "+(engine.MaxRepeats==0?"Unlimited repeats.":"Limit: "+engine.MaxRepeats+"."));UpdateStatus();}
 void SetRunning(bool running){start.Enabled=!running&&conversations.Items.Count>0&&!string.IsNullOrWhiteSpace(prompt.Text);stop.Enabled=running;refresh.Enabled=!running;conversations.Enabled=!running;prompt.ReadOnly=running;delay.Enabled=!running;limit.Enabled=!running;initial.Enabled=!running;presetContinue.Enabled=!running;presetWork.Enabled=!running;presetVerify.Enabled=!running;}
 void Stop(string reason){if(accountOperation&&accountCancellation!=null)accountCancellation.Cancel();epoch++;engine.Stop(reason);SetRunning(false);UpdateStatus();}
 void UpdateStatus(){headline.Text=engine.State??"Stopped";headline.AutoEllipsis=true;tips.SetToolTip(headline,headline.Text);counter.Text=engine.Sent.ToString();sessionVisual.Running=engine.Armed;sessionVisual.State=engine.State;sessionVisual.DelaySeconds=engine.DelaySeconds;sessionVisual.Count=engine.Sent;sessionVisual.Invalidate();tray.Text="AntiGravity Repeater - "+(engine.Armed?"running":"stopped");if(lastState!=engine.State){lastState=engine.State;Log(engine.State);}if(!engine.Armed){SetRunning(false);sessionStarted=null;}}
 async Task Poll(){if(polling||closing||accountOperation||!engine.Armed)return;polling=true;int run=epoch;try{
  Conversation c=conversations.SelectedItem as Conversation;if(c==null)return;Conversation current=null;try{current=await c.Endpoint.Get(selectedId);}catch{failures++;}
  if(run!=epoch||!engine.Armed||closing)return;
  if(current==null){var all=await DiscoverAll();if(run!=epoch||!engine.Armed||closing)return;current=all.FirstOrDefault(x=>x.Id==selectedId);if(current!=null){int index=conversations.SelectedIndex;conversations.Items[index]=current;conversations.SelectedIndex=index;Log("Reconnected to the same conversation.");}}
  if(run!=epoch||!engine.Armed||closing)return;
  if(current==null){engine.Observe(null,DateTime.UtcNow);UpdateStatus();return;}
  failures=0;
  if(engine.Observe(current,DateTime.UtcNow)){
   if(!await CheckAllowance(current)||run!=epoch||!engine.Armed||closing)return;
   string blocked=await current.Endpoint.GetBlockReason(current);if(run!=epoch||!engine.Armed||closing)return;if(blocked!=null){Stop(blocked);return;}
   object request=await current.Endpoint.PrepareSend(current,activePrompt);if(run!=epoch||!engine.Armed||closing)return;
   // Re-read status immediately before mutation: never enqueue behind an active agent.
   var fresh=await current.Endpoint.Get(selectedId);if(run!=epoch||!engine.Armed||closing)return;
   if(fresh==null||!fresh.IsIdle||fresh.Fingerprint!=current.Fingerprint){engine.Observe(fresh,DateTime.UtcNow);UpdateStatus();return;}
   if(!budget.CanSend(settings.DailySendBudget,DateTime.UtcNow)){Stop("Daily request budget reached. Resets at midnight IST.");DrawUsage();return;}
   budget.Reserve(DateTime.UtcNow);DrawUsage();engine.MarkSending(fresh,DateTime.UtcNow);UpdateStatus();
   try{await fresh.Endpoint.Call("SendUserCascadeMessage",request);engine.MarkAccepted();Log("Prompt accepted by AntiGravity for the selected conversation.");}catch{engine.SendFailed();Log("No automatic retry: a timed-out request may already have been delivered.");}
  }
  UpdateStatus();
 }catch(Exception ex){if(run==epoch && engine.Armed){engine.Observe(null,DateTime.UtcNow);UpdateStatus();if(failures++%5==0)Log("Connection unavailable ("+ex.GetType().Name+"); retrying the same conversation.");}}finally{polling=false;}}
}
